<?php
namespace App\Models;
use App\Enums\AppointmentStatus; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasOne;
class Appointment extends Model { protected $fillable=['user_id','provider_id','service_id','starts_at','ends_at','duration_minutes','price','currency','status','hold_expires_at','cancelled_at','cancellation_reason','rescheduled_at','reminder_queued_at','idempotency_key']; protected function casts(): array { return ['starts_at'=>'immutable_datetime','ends_at'=>'immutable_datetime','hold_expires_at'=>'immutable_datetime','cancelled_at'=>'immutable_datetime','rescheduled_at'=>'immutable_datetime','reminder_queued_at'=>'immutable_datetime','price'=>'decimal:2','duration_minutes'=>'integer','status'=>AppointmentStatus::class]; } public function user(): BelongsTo { return $this->belongsTo(User::class); } public function provider(): BelongsTo { return $this->belongsTo(Provider::class); } public function service(): BelongsTo { return $this->belongsTo(Service::class); } public function payment(): HasOne { return $this->hasOne(Payment::class); } }
